#undef QT_NO_CAST_FROM_ASCII
#undef QT_NO_CAST_FROM_BYTEARRAY
#undef QT_NO_CAST_TO_ASCII
#include "ResearchSlides.cpp"
#include <QElapsedTimer>
#include <QThread>
#include <QJsonArray>
static void settle(int ms=200){QElapsedTimer timer;timer.start();while(timer.elapsed()<ms){QCoreApplication::processEvents();QThread::msleep(2);}}
int main(int argc,char **argv){const QString report=QString::fromLocal8Bit(argv[1]);argc=1;TWApp app(argc,argv);app.setQuitOnLastWindowClosed(false);QTimer::singleShot(80,&app,[&]{
 QJsonArray checks;int failures=0;auto check=[&](const QString &name,bool passed){checks.append(QJsonObject{{"name",name},{"passed",passed}});QFile file(report);if(file.open(QIODevice::WriteOnly))file.write(QJsonDocument(QJsonObject{{"checks",checks},{"failures",failures+=!passed}}).toJson());};
 const QString root=QFileInfo(report).absolutePath()+"/main.tex";
 const QString original=QStringLiteral("\\documentclass{beamer}\n\\title{Original title}\n\\author{Author}\n\\begin{document}\n% A comment\n\\begin{frame}{A}\nA\u00a0B\n\\end{frame}\n% B comment\n\\begin{frame}{B}\nB\n\\end{frame}\n\\begin{frame}{C}\nC\n\\end{frame}\n\\section{Boundary}\n\\begin{frame}[label=target]{D}\nD\n\\end{frame}\n\\againframe{target}\n\\end{document}\n");
 QFile file(root);if(file.open(QIODevice::WriteOnly))file.write(original.toUtf8());file.close();Tw::Settings().setValue("openPDFwithTeX",false);auto *w=new TeXDocumentWindow(root);w->resize(1400,900);w->show();settle(900);
 const auto deck=Research::parseSlideDeck(root);check("automatic mode recognizes the private fixture",w->property("researchSlideMode").toBool()&&deck.frames.size()==5);
 auto *list=dynamic_cast<Research::SlideList *>(w->findChild<QListWidget *>("researchSlideList"));check("directory supports extended selection and native move drag",list&&list->selectionMode()==QAbstractItemView::ExtendedSelection&&list->dragDropMode()==QAbstractItemView::InternalMove);
 auto reset=[&]{w->editor()->undo();check("operation has exactly one undo restoring all source bytes",w->textDoc()->editorText()==original);};QString reason;
 check("multi-copy succeeds without labels",Research::editSlideSelection(w,deck,{0,1},Research::SlideEdit::Duplicate,-1,&reason));auto after=Research::parseSlideDeck(root,{{Research::path(root),w->textDoc()->editorText()}});check("multi-copy preserves slide order and NBSP",after.frames.size()==7&&after.frames[2].title=="A"&&after.frames[3].title=="B"&&w->textDoc()->editorText().count(QChar::Nbsp)==2);reset();
 check("nonadjacent multi-delete succeeds",Research::editSlideSelection(w,deck,{0,2},Research::SlideEdit::Delete,-1,&reason));after=Research::parseSlideDeck(root,{{Research::path(root),w->textDoc()->editorText()}});check("multi-delete preserves other slides and surrounding comments",after.frames.size()==3&&after.frames.first().title=="B"&&w->textDoc()->editorText().contains("% A comment\n% B comment"));reset();
 check("drag validation changes neither source nor undo state",Research::editSlideSelection(w,deck,{0,1},Research::SlideEdit::Down,3,&reason,false)&&w->textDoc()->editorText()==original);
 check("contiguous block moves after the target",Research::editSlideSelection(w,deck,{0,1},Research::SlideEdit::Down,3,&reason));after=Research::parseSlideDeck(root,{{Research::path(root),w->textDoc()->editorText()}});check("drop order is C A B D with all content preserved",after.frames.size()==5&&after.frames[0].title=="C"&&after.frames[1].title=="A"&&after.frames[2].title=="B"&&w->textDoc()->editorText().contains("A\u00a0B"));reset();
 check("section boundary blocks a drag without changing source",!Research::editSlideSelection(w,deck,{0},Research::SlideEdit::Down,4,&reason)&&!reason.isEmpty()&&w->textDoc()->editorText()==original);
 check("labelled copy and referenced deletion remain protected",!Research::editSlideSelection(w,deck,{3},Research::SlideEdit::Duplicate,-1,&reason)&&!Research::editSlideSelection(w,deck,{3},Research::SlideEdit::Delete,-1,&reason)&&w->textDoc()->editorText()==original);
 w->editor()->setReadOnly(true);check("read-only source rejects bulk edits",!Research::editSlideSelection(w,deck,{0,1},Research::SlideEdit::Delete,-1,&reason));w->editor()->setReadOnly(false);settle(800);
 if(list){const QRect before=list->visualItemRect(list->item(2));list->animateGap(2);settle(40);const double intermediate=list->property("researchSlideGaps").toMap().value("2").toDouble();check("drag gap interpolates rather than jumping",intermediate>0&&intermediate<14);settle(180);check("drag gap reaches bounded height without changing data",list->visualItemRect(list->item(2)).height()==before.height()+14&&w->textDoc()->editorText()==original);list->grab().save(QFileInfo(report).absolutePath()+"/drag-gap.png");list->animateGap(-1);settle(180);check("cancel restores original geometry and content",list->visualItemRect(list->item(2))==before&&w->textDoc()->editorText()==original);Tw::Settings().setValue("researchReduceMotion",true);list->animateGap(2);check("reduced motion places gap immediately",list->property("researchSlideGaps").toMap().value("2").toInt()==14);list->animateGap(-1);Tw::Settings().setValue("researchReduceMotion",false);}
 auto *options=w->findChild<QAction *>("researchDocumentOptionsAction");bool edited=false;QTimer::singleShot(100,&app,[&]{if(auto *dialog=w->findChild<QDialog *>("researchSlideDocumentOptions")){auto *title=dialog->findChild<QLineEdit *>("researchDocument_title");auto *aspect=dialog->findChild<QComboBox *>("researchDocumentAspect");title->setText("Revised title");aspect->setCurrentIndex(1);dialog->findChild<QDialogButtonBox *>()->button(QDialogButtonBox::Save)->click();edited=true;}});if(options)options->trigger();check("document fields edit exact declarations and preserve slides",edited&&w->textDoc()->editorText().contains("\\title{Revised title}")&&w->textDoc()->editorText().contains("aspectratio=169")&&Research::parseSlideDeck(root,{{Research::path(root),w->textDoc()->editorText()}}).frames.size()==5);reset();settle(800);
 auto *profile=w->findChild<QAction *>("researchPresentationProfile2");if(profile)profile->trigger();check("speaker profile explicitly adds an undoable preamble setting",w->textDoc()->editorText().contains("show notes on second screen=right")&&w->textDoc()->editorText().contains("\\title{Original title}"));{QFile output(QFileInfo(report).absolutePath()+"/speaker-profile.tex");if(output.open(QIODevice::WriteOnly))output.write(w->textDoc()->editorText().toUtf8());}reset();settle(600);
 if(auto *button=w->findChild<QToolButton *>("researchSlideAddButton")){int index=0;for(int kind=0;kind<6;++kind){++index;auto *layout=button->menu()->findChild<QToolButton *>(QString("researchLayout%1").arg(kind));check(QString("layout tile %1 exists").arg(kind),layout);if(!layout)continue;auto *c=Research::controller(w);QElapsedTimer ready;ready.start();while((c->dirty||c->busy||c->deck.sources.value(Research::path(root))!=w->textDoc()->editorText())&&ready.elapsed()<10000)settle(20);list->setCurrentRow(1);ready.restart();while((c->dirty||c->busy||c->deck.sources.value(Research::path(root))!=w->textDoc()->editorText())&&ready.elapsed()<10000)settle(20);check(QString("layout %1 starts after directory refresh").arg(index-1),!c->dirty&&!c->busy&&c->deck.sources.value(Research::path(root))==w->textDoc()->editorText());layout->click();settle(700);const auto added=Research::parseSlideDeck(root,{{Research::path(root),w->textDoc()->editorText()}});check(QString("layout %1 inserts a literal frame").arg(index-1),added.frames.size()==6);QFile output(QFileInfo(report).absolutePath()+QString("/layout-%1.tex").arg(index-1));if(output.open(QIODevice::WriteOnly))output.write(w->textDoc()->editorText().toUtf8());reset();settle(600);}}
 const auto windows=TeXDocumentWindow::documentList();if(auto *newSlides=w->findChild<QAction *>("researchNewSlides"))newSlides->trigger();settle(900);TeXDocumentWindow *created=nullptr;for(auto *other:TeXDocumentWindow::documentList())if(!windows.contains(other))created=other;check("new slide template starts unsaved in slide mode",created&&created->untitled()&&created->property("researchSlideMode").toBool()&&created->findChild<QListWidget *>("researchSlideList")&&created->findChild<QListWidget *>("researchSlideList")->count()==3);
 for(auto *other:TeXDocumentWindow::documentList())other->setModified(false);app.exit(failures?1:0);
 });return app.exec();}
